using System;
using System.Drawing;
using System.IO;
using System.Text;
using System.Linq;
using System.Collections.Generic;

namespace Sneg {
 internal static class SelfTests {
  static readonly List<string> results=new List<string>();static int failed;
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static void Near(double a,double b,double tolerance,string message){Assert(Math.Abs(a-b)<=tolerance,message+": "+a+" vs "+b);}
  static void Test(string id,string title,Action run){try{run();results.Add("| "+id+" | "+title+" | Пройден | — |");}catch(Exception e){failed++;results.Add("| "+id+" | "+title+" | Не пройден | "+e.Message.Replace("|","/")+" |");}}
  static SnowWorld World(){var w=new SnowWorld(new Settings(),17);w.Monitors.Add(new Rectangle(-800,0,1600,1000));w.Emitting=false;return w;}
  public static int Run(string dir){Directory.CreateDirectory(dir);results.Clear();failed=0;
   Test("A01","Фиксированный шаг при 30 и 144 кадрах/с",delegate{var a=World();var b=World();a.Emitting=b.Emitting=true;for(int i=0;i<300;i++)a.Advance(1.0/30);for(int i=0;i<1440;i++)b.Advance(1.0/144);Near(a.Time,b.Time,1e-8,"Время");Assert(a.Flakes.Count==b.Flakes.Count,"Число частиц");for(int i=0;i<a.Flakes.Count;i++){Near(a.Flakes[i].X,b.Flakes[i].X,.001,"X");Near(a.Flakes[i].Y,b.Flakes[i].Y,.001,"Y");}});
   Test("A02","Снежинки пересекают тонкую опору без проваливания",delegate{var w=World();var s=new Surface(1,-100,30,200);w.Surfaces.Add(s);w.Flakes.Add(new Flake{X=0,Y=-10,VY=10000,Radius=2,Alpha=200});w.Advance(SnowWorld.Step);Assert(w.Flakes.Count==0&&s.Area>0,"Снег не осел");});
   Test("A03","Быстрый шар не перескакивает опору",delegate{var w=World();var s=new Surface(1,-100,20,200);w.Surfaces.Add(s);var b=new Ball{X=0,Y=0,VY=3000,Area=Math.PI*25};w.Balls.Add(b);w.Advance(SnowWorld.Step);Assert(b.Support==s,"Опора пропущена");Near(b.Y,15,.01,"Высота");});
   Test("A04","Сохранение площади снега при скатывании",delegate{var w=World();var s=new Surface(1,-300,250,600);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=18;w.Surfaces.Add(s);double before=s.Area;w.Tool=Tool.Snowball;w.BeginDrag(new PointF(-250,236));w.Drag(new PointF(200,236));Assert(w.Held!=null&&w.Held.Radius>4,"Шар не собран");Near(before,s.Area+w.Held.Area,.0001,"Баланс снега");Assert(w.Held.Radius<=52.001,"Предел размера");w.EndDrag(new PointF(200,236));});
   Test("A05","Повторное движение по пустому снегу не создаёт массу",delegate{var s=new Surface(1,0,200,100);s.Heights[4]=10;double before=s.Area,q=s.Take(25,40,9999);q+=s.Take(25,40,9999);Near(before,q,.0001,"Повторный сбор");Near(s.Area,0,.0001,"Остаток");});
   Test("A06","Изменение ширины сохраняет удержанную площадь",delegate{var s=new Surface(1,0,200,123);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=i*.7;double before=s.Area,lost=s.Resize(71);Near(before,s.Area+lost,1e-6,"Уменьшение");before=s.Area;lost=s.Resize(247);Near(before,s.Area,1e-6,"Расширение");Near(lost,0,1e-6,"Потери при расширении");});
   Test("A07","Осыпание уменьшает уклон и сохраняет площадь",delegate{var s=new Surface(1,0,200,180);s.Heights[10]=60;double before=s.Area;for(int i=0;i<200;i++)s.Relax();Near(before,s.Area,1e-6,"Площадь после осыпания");Assert(s.Heights[10]<60&&s.Heights.All(x=>x>=0),"Уклон не сглажен");});
   Test("A08","Перекрытая часть поверхности не принимает снег",delegate{var w=World();var s=new Surface(1,0,30,200);s.Occluders.Add(new Rectangle(0,0,100,100));w.Surfaces.Add(s);w.Flakes.Add(new Flake{X=50,Y=-10,VY=10000,Radius=2});w.Advance(SnowWorld.Step);Near(s.Area,0,.001,"Накопление под перекрытием");Assert(!s.Visible(50,29)&&s.Visible(150,29),"Видимость");});
   Test("A09","Отрицательные координаты",delegate{var w=World();var s=new Surface(1,-700,200,200);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=10;w.Surfaces.Add(s);Assert(w.PickSnow(new PointF(-650,195))==s,"Выбор снега слева от основного монитора");Assert(w.PickSnow(new PointF(20,195))==null,"Лишняя область ввода");});
   Test("A10","Пауза и пробуждение без скачка",delegate{var w=World();var f=new Flake{X=0,Y=0,VY=100,Radius=1};w.Flakes.Add(f);w.Paused=true;w.Advance(.1);Near(f.Y,0,1e-6,"Пауза");w.Paused=false;w.Advance(30);Near(f.Y,0,1e-6,"Длительный разрыв");w.Advance(SnowWorld.Step);Assert(f.Y>0&&f.Y<2,"Продолжение");});
   Test("A11","Повреждённые настройки и допустимые пределы",delegate{string path=Path.Combine(dir,"settings-test.xml");File.WriteAllText(path,"<invalid>не XML");var s=Settings.Load(path);Assert(s.Intensity==90,"Восстановление значений");s.Intensity=999999;s.Size=-1;s.Fps=1;s.HotKey=0;s.Validate();Assert(s.Intensity==350&&s.Size==40&&s.Fps==60&&s.HotKey==83,"Границы значений");s.Save(path);var t=Settings.Load(path);Assert(t.Intensity==350&&t.Size==40,"Сохранение и чтение");File.Delete(path);});
   Test("A12","Сто циклов очистки и отмены инструмента",delegate{var w=World();var s=new Surface(1,0,200,200);w.Surfaces.Add(s);for(int k=0;k<100;k++){for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=15;w.Tool=Tool.Snowball;w.BeginDrag(new PointF(50,190));w.Clear();Assert(w.Held==null&&w.Balls.Count==0&&w.Flakes.Count==0&&s.Area==0,"Нарушено состояние после очистки");w.Tool=Tool.None;}});
   Test("A13","Свёрнутая поверхность скрывает и замораживает шар",delegate{var w=World();var s=new Surface(1,0,200,200){Active=false};var b=new Ball{X=50,Y=190,Area=Math.PI*100,Support=s};w.Surfaces.Add(s);w.Balls.Add(b);w.Advance(.1);Near(b.Y,190,.001,"Скрытый шар сдвинулся");Assert(!b.Visible,"Скрытый шар виден");s.Active=true;w.Advance(SnowWorld.Step);Assert(b.Visible&&b.Support==s,"Восстановление");});
   Test("A14","Непрерывное столкновение двух сфер",delegate{double t;Assert(SnowWorld.SweepCircle(0,-100,0,100,0,0,20,out t),"Пересечение пропущено");Near(t,.4,1e-9,"Время контакта");Assert(!SnowWorld.SweepCircle(100,-100,100,100,0,0,20,out t),"Ложное столкновение");});
   Test("A15","Снегоуборщик действительно удаляет снег",delegate{var w=World();var s=new Surface(-1,-800,1000,1600){Floor=true};for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=12;w.Surfaces.Add(s);double before=s.Area;w.StartPlow();for(int i=0;i<1500;i++)w.Advance(SnowWorld.Step);Assert(s.Area<before*.01&&!w.Plowing,"Полоса не очищена");});
   Test("A16","Ограничение количества частиц",delegate{var w=World();w.Emitting=true;w.Settings.Intensity=350;w.EffectiveLimit=150;for(int i=0;i<1200;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count<=150,"Превышен предел");});
   Test("A17","Варежка и лопата очищают локально",delegate{foreach(var tool in new[]{Tool.Mitten,Tool.Shovel}){var w=World();var s=new Surface(1,0,200,600);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=15;w.Surfaces.Add(s);w.Tool=tool;double before=s.Area;w.BeginDrag(new PointF(300,190));Assert(s.Area<before&&s.Area>before*.5,"Локальная очистка "+tool);Near(s.Heights[0],15,.001,"Дальний участок");}});
   Test("A18","Снеговик из трёх шаров",delegate{var w=World();var s=new Surface(1,-100,300,200);w.Surfaces.Add(s);var bottom=new Ball{X=0,Y=275,Area=Math.PI*625,Support=s};var middle=new Ball{X=0,Y=231,Area=Math.PI*400,Support=s,OnBall=bottom};var top=new Ball{X=0,Y=170,VY=1000,Area=Math.PI*225};w.Balls.Add(bottom);w.Balls.Add(middle);w.Balls.Add(top);for(int i=0;i<30;i++)w.Advance(SnowWorld.Step);Assert(top.OnBall==middle&&top.Face,"Снеговик не распознан");});
   Test("A19","Бросок использует недавнюю скорость мыши",delegate{var w=World();w.Tool=Tool.Snowball;var ball=new Ball{X=0,Y=100,Area=Math.PI*100};w.Balls.Add(ball);w.BeginDrag(new PointF(0,100));w.Advance(.05);w.Drag(new PointF(20,90));w.Advance(.05);w.EndDrag(new PointF(40,80));Assert(ball.VX>100&&ball.VY<0&&!ball.Held,"Неверная скорость броска");});
   Test("A20","Область ввода совпадает со снегом и шарами",delegate{var w=World();var s=new Surface(1,0,200,300);s.Heights[10]=10;w.Surfaces.Add(s);Assert(w.PickSnow(new PointF(61,195))==s,"Не выбран сугроб");Assert(w.PickSnow(new PointF(61,100))==null,"Перехват пустого места");s.Occluders.Add(new Rectangle(0,0,300,220));Assert(w.PickSnow(new PointF(61,195))==null,"Перехват за передним окном");});
   Test("A21","Собранный на кромке шар остаётся на опоре",delegate{var w=World();var s=new Surface(1,0,200,400);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=15;w.Surfaces.Add(s);w.Tool=Tool.Snowball;w.BeginDrag(new PointF(50,192));w.Drag(new PointF(250,192));w.EndDrag(new PointF(250,192));var b=w.Balls[0];for(int i=0;i<30;i++)w.Advance(SnowWorld.Step);Assert(b.Support==s&&b.Y+b.Radius<=s.Y+.1,"Шар провалился при отпускании");});
   Test("A22","Катящиеся шары не пересекаются",delegate{var w=World();var s=new Surface(1,0,300,500);w.Surfaces.Add(s);var a=new Ball{X=100,Y=280,Area=Math.PI*400,Support=s,VX=150};var b=new Ball{X=140,Y=280,Area=Math.PI*400,Support=s};w.Balls.Add(a);w.Balls.Add(b);for(int i=0;i<120;i++)w.Advance(SnowWorld.Step);Assert(b.X-a.X>=39.9,"Шары пересеклись");});
   Test("A23","Закруглённый контур без треугольных углов",delegate{var s=new Surface(1,0,200,300);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=20;using(var path=ScenePainter.SnowPath(s)){Assert(!path.IsVisible(.5f,180.5f),"Остался острый верхний угол");Assert(path.IsVisible(15,182)&&path.IsVisible(150,185),"Закругление срезало основную часть сугроба");Assert(!path.IsVisible(-15,195)&&!path.IsVisible(150,175),"Контур выступает за снег");}Near(s.Area,6000,.001,"Рисование изменило количество снега");});
   Test("A24","Осыпание переносит снег в падающие частицы с ускорением",delegate{var w=World();var s=new Surface(1,0,200,300);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=20;w.Surfaces.Add(s);double before=s.Area;w.Shed(s,20,10);Near(s.Area,0,.001,"Сугроб остался на окне");Near(w.Flakes.Sum(f=>f.SnowArea),before,.001,"Баланс осыпавшегося снега");Assert(w.Flakes.All(f=>f.Debris&&f.IgnoreSurface==1),"Частицы не отсоединены от старой опоры");var flake=w.Flakes[0];double y=flake.Y,v=flake.VY;for(int i=0;i<40;i++)w.Advance(SnowWorld.Step);Assert(flake.VY>v&&flake.Y>y&&flake.Y>s.Y,"Нет ускоренного падения сквозь старую опору");});
   Test("A25","Перемещение окна оставляет падающий снег на прежнем месте",delegate{var w=World();var wi=new WindowInfo{Handle=new IntPtr(123456),Pid=17,Surface=true,Bounds=new Rectangle(50,200,300,150)};w.Sync(new List<WindowInfo>{wi},new List<Rectangle>());var s=w.Surfaces.First(v=>!v.Floor);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=12;var ball=new Ball{X=120,Y=190,Area=Math.PI*100,Support=s};w.Balls.Add(ball);wi.Bounds=new Rectangle(110,260,300,150);w.Sync(new List<WindowInfo>{wi},new List<Rectangle>());Assert(s.Left==110&&s.Y==260&&s.Area==0,"Снег перенесён вместе с окном");Assert(w.Flakes.Count>0&&w.Flakes.All(f=>f.Y<200),"Анимация началась на новом месте окна");Assert(ball.Support==null&&ball.X==120&&ball.Y==190,"Шар не потерял старую опору");int n=w.Flakes.Count;wi.Bounds=new Rectangle(150,280,300,150);w.Sync(new List<WindowInfo>{wi},new List<Rectangle>());Assert(w.Flakes.Count==n,"Пустое окно создало дополнительный снег");});
   Test("A26","Нижний сугроб привязан к экрану и не закрывается окнами",delegate{var w=World();var wi=new WindowInfo{Handle=new IntPtr(123456),Pid=17,Surface=true,Bounds=new Rectangle(-800,0,1600,1000)};w.Sync(new List<WindowInfo>{wi},new List<Rectangle>{new Rectangle(-800,0,1600,940)});var floor=w.Surfaces.First(s=>s.Floor);Near(floor.Y,1000,.001,"Вместо края экрана использована рабочая область");Assert(floor.Occluders.Count==0&&floor.Visible(0,999),"Низ скрыт окном");});
   Test("A27","Снег перед окнами доходит до нижнего края",delegate{var w=World();var wi=new WindowInfo{Handle=new IntPtr(123456),Pid=17,Surface=true,Bounds=new Rectangle(-800,950,1600,50)};w.Sync(new List<WindowInfo>{wi},new List<Rectangle>());var floor=w.Surfaces.First(s=>s.Floor);var ledge=w.Surfaces.First(s=>!s.Floor);w.Flakes.Add(new Flake{X=0,Y=900,VY=10000,Radius=2,GroundOnly=true});w.Advance(SnowWorld.Step);w.Advance(SnowWorld.Step);Assert(floor.Area>0&&ledge.Area==0&&w.Flakes.Count==0,"Снег не дошёл до нижнего края");});
   Test("A28","Естественное накопление внизу при открытом окне",delegate{var w=World();w.Emitting=true;var wi=new WindowInfo{Handle=new IntPtr(123456),Pid=17,Surface=true,Bounds=new Rectangle(-800,300,1600,700)};w.Sync(new List<WindowInfo>{wi},new List<Rectangle>());for(int i=0;i<2400;i++)w.Advance(SnowWorld.Step);Assert(w.Surfaces.First(s=>s.Floor).Area>100,"Нижний слой не пополняется");Assert(w.Surfaces.First(s=>!s.Floor).Area>100,"Пропало накопление на окнах");});
   Test("A29","Осыпавшийся снег оседает ниже",delegate{var w=World();var s=new Surface(1,-150,200,300);var floor=new Surface(-1,-800,1000,1600){Floor=true};w.Surfaces.Add(s);w.Surfaces.Add(floor);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=14;w.Shed(s,0,0);for(int i=0;i<360;i++)w.Advance(SnowWorld.Step);Assert(floor.Area>0&&s.Area==0,"Снег не осел на нижней поверхности");Assert(w.Flakes.Count==0,"Осыпание зависло в воздухе");});
   Test("A30","Полный сугроб осыпается с обоих краёв с сохранением снега",delegate{var w=World();var s=new Surface(1,-150,300,300);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=60;w.Surfaces.Add(s);double before=s.Area;for(int i=0;i<60;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Any(f=>f.X<s.Left&&f.VX<0)&&w.Flakes.Any(f=>f.X>s.Left+s.Width&&f.VX>0),"Нет осыпания с двух краёв");Assert(s.Area<before,"Сугроб не сбросил снег");Near(s.Area+s.OverflowLeft+s.OverflowRight+w.Flakes.Sum(f=>f.SnowArea),before,.0001,"Баланс снега при осыпании");});
   Test("A31","Избыток снегопада попадает в очередь осыпания",delegate{var w=World();var s=new Surface(1,-150,300,300);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=60;w.Surfaces.Add(s);double before=s.Area;Near(s.Add(0,1000),0,.001,"Переполнение добавило высоту");Near(s.OverflowLeft+s.OverflowRight,1000,.001,"Излишек потерян");for(int i=0;i<12;i++)w.Advance(SnowWorld.Step);Near(s.Area+s.OverflowLeft+s.OverflowRight+w.Flakes.Sum(f=>f.SnowArea),before+1000,.001,"Баланс излишка");Assert(s.Heights.All(h=>h<=60.001),"Превышена высота");});
   Test("A32","Незаполненное окно не осыпается само",delegate{var w=World();var s=new Surface(1,0,300,300);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=30;w.Surfaces.Add(s);for(int i=0;i<240;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count==0&&s.OverflowLeft==0&&s.OverflowRight==0,"Преждевременное осыпание");});
   Test("A33","Нижний сугроб не осыпается за экран",delegate{var w=World();var s=new Surface(-1,-800,1000,1600){Floor=true};for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=60;w.Surfaces.Add(s);for(int i=0;i<120;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count==0&&s.OverflowLeft==0&&s.OverflowRight==0,"Осыпание нижней границы");});
   Test("A34","При полном бюджете осыпание ждёт и очищается без остатка",delegate{var w=World();w.EffectiveLimit=150;var s=new Surface(1,-150,300,300);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=60;w.Surfaces.Add(s);for(int i=0;i<150;i++)w.Flakes.Add(new Flake{X=0,Y=-1000,Debris=true,SnowArea=1,Radius=1});double before=s.Area+150;for(int i=0;i<60;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count<=150&&s.OverflowLeft+s.OverflowRight>0,"Очередь/предел частиц");Near(s.Area+s.OverflowLeft+s.OverflowRight+w.Flakes.Sum(f=>f.SnowArea),before,.001,"Потеря при полном бюджете");w.Clear();Assert(s.Area==0&&s.OverflowLeft==0&&s.OverflowRight==0&&w.Flakes.Count==0,"Остаток после очистки");});
   Test("A35","Текстуры инструментов содержат фактуру и прозрачный фон",delegate{foreach(var image in new[]{ToolArt.Mitten,ToolArt.Shovel}){var colors=new HashSet<int>();int visible=0;for(int y=0;y<image.Height;y+=2)for(int x=0;x<image.Width;x+=2){var c=image.GetPixel(x,y);if(c.A>0){visible++;colors.Add(c.ToArgb());}}Assert(image.GetPixel(0,0).A==0&&visible>300&&colors.Count>100,"Пустое или одноцветное изображение");}Directory.CreateDirectory(Path.Combine(dir,"Evidence"));ToolArt.Mitten.Save(Path.Combine(dir,"Evidence/tool-mitten-v03.png"),System.Drawing.Imaging.ImageFormat.Png);ToolArt.Shovel.Save(Path.Combine(dir,"Evidence/tool-shovel-v03.png"),System.Drawing.Imaging.ImageFormat.Png);});
   Test("A36","Изображение инструмента не расширяет область захвата мыши",delegate{var w=World();w.Tool=Tool.Mitten;w.ShowTool=true;w.Pointer=new PointF(130,150);using(var input=new Bitmap(260,220))using(var visual=new Bitmap(260,220)){using(var g=Graphics.FromImage(input))ScenePainter.Draw(g,w,true,false,0);using(var g=Graphics.FromImage(visual))ScenePainter.Draw(g,w,false,false,0);int hit=0,seen=0;for(int y=0;y<220;y+=2)for(int x=0;x<260;x+=2){if(input.GetPixel(x,y).A>0)hit++;if(visual.GetPixel(x,y).A>0)seen++;}Assert(hit==0&&seen>100,"Изображение перехватывает мышь или не рисуется");}});
   Test("A37","Отмена инструмента снимает анимацию нажатия",delegate{var w=World();w.Tool=Tool.Mitten;w.BeginDrag(new PointF(0,0));Assert(w.ToolDown,"Нажатие не записано");w.CancelDrag();Assert(!w.ToolDown&&w.Held==null,"Нажатие осталось после отмены");});
   Test("A38","Глубокий сугроб даёт более крупные кучки",delegate{var thin=World();var deep=World();var a=new Surface(1,-300,300,600);var b=new Surface(1,-300,300,600);for(int i=0;i<a.Heights.Length;i++){a.Heights[i]=6;b.Heights[i]=55;}thin.Surfaces.Add(a);deep.Surfaces.Add(b);double massA=a.Area,massB=b.Area;thin.Shed(a,0,0);deep.Shed(b,0,0);Assert(thin.Flakes.All(f=>f.Clump)&&deep.Flakes.All(f=>f.Clump),"Падение осталось точками");Assert(deep.Flakes.Average(f=>f.Radius)>thin.Flakes.Average(f=>f.Radius)*2,"Размер не зависит от количества снега");Assert(deep.Flakes.Count<=32&&deep.Flakes.Average(f=>f.Radius)>15,"Кучки слишком мелкие или их слишком много");Near(thin.Flakes.Sum(f=>f.SnowArea),massA,.001,"Масса тонкого слоя");Near(deep.Flakes.Sum(f=>f.SnowArea),massB,.001,"Масса глубокого слоя");});
   Test("A39","Комки вращаются и сохраняют размер в полёте",delegate{var w=World();var s=new Surface(1,-200,300,400);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=30;w.Surfaces.Add(s);w.Shed(s,15,0);var f=w.Flakes[0];double radius=f.Radius,spin=f.Spin,y=f.Y;for(int i=0;i<24;i++)w.Advance(SnowWorld.Step);Assert(f.Y>y&&Math.Abs(f.Spin-spin)>.001,"Нет движения комка");Near(radius,f.Radius,.001,"Размер меняется без изменения количества снега");});
   Test("A40","Закруглённый свес огибает рамку ниже верхней границы",delegate{var w=World();var s=new Surface(1,0,200,300);for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=20;w.Surfaces.Add(s);using(var path=ScenePainter.SnowPath(s)){int left=0,right=0;PointF selected=new PointF();for(int y=202;y<218;y++)for(int x=-7;x<8;x++){if(path.IsVisible(x,y)){left++;selected=new PointF(x,y);}if(path.IsVisible(300+x,y))right++;}Assert(left>5&&right>5,"Нет снежного свеса под углами окна");Assert(!path.IsVisible(150,215)&&!path.IsVisible(260,220),"Снег закрыл содержимое окна");Assert(w.PickSnow(selected)==s,"Свес не доступен инструменту");}});
   Test("A41","Текстура снега детальная и не мерцает между кадрами",delegate{using(var a=new Bitmap(140,140))using(var b=new Bitmap(140,140)){using(var g=Graphics.FromImage(a))SnowArt.Sphere(g,70,70,58);using(var g=Graphics.FromImage(b))SnowArt.Sphere(g,70,70,58);var colors=new HashSet<int>();for(int y=15;y<125;y++)for(int x=15;x<125;x++){var p=a.GetPixel(x,y);Assert(p==b.GetPixel(x,y),"Случайное мерцание фактуры");if(p.A>0)colors.Add(p.ToArgb());}Assert(colors.Count>500&&a.GetPixel(0,0).A==0,"Нет зернистой текстуры/прозрачности");var light=a.GetPixel(50,45);var shade=a.GetPixel(95,105);Assert(light.R+light.G+light.B>shade.R+shade.G+shade.B+25,"Нет объёмного освещения");}});
   Test("A42","Снегоуборщик жёлтый, с голубой кабиной, гусеницами и отвалом",delegate{int yellow=0,blue=0,dark=0,steel=0;for(int y=0;y<SnowArt.Plow.Height;y++)for(int x=0;x<SnowArt.Plow.Width;x++){var p=SnowArt.Plow.GetPixel(x,y);if(p.A<150)continue;if(p.R>170&&p.G>100&&p.B<100)yellow++;if(p.B>p.R*1.2&&p.B>120)blue++;if(p.R<90&&p.G<100&&p.B<110)dark++;if(x>215&&p.R>130&&p.G>145&&p.B>160)steel++;}Assert(yellow>1000&&blue>200&&dark>500&&steel>300,"Не хватает деталей машины");Directory.CreateDirectory(Path.Combine(dir,"Evidence"));SnowArt.Plow.Save(Path.Combine(dir,"Evidence/plow-v04.png"),System.Drawing.Imaging.ImageFormat.Png);});
   Test("A43","У снеговика красный шарф, морковка и угольные пуговицы",delegate{using(var image=new Bitmap(220,300)){var middle=new Ball{X=110,Y=160,Area=Math.PI*900};var head=new Ball{X=110,Y=99,Area=Math.PI*1024,OnBall=middle,Face=true};using(var g=Graphics.FromImage(image))SnowArt.Snowman(g,head);int red=0,orange=0,coal=0;for(int y=50;y<210;y++)for(int x=60;x<155;x++){var p=image.GetPixel(x,y);if(p.A<100)continue;if(p.R>140&&p.R>p.G*1.8&&p.G<100)red++;if(p.R>160&&p.G>70&&p.G<190&&p.B<90)orange++;if(y>140&&p.R<80&&p.G<90&&p.B<110)coal++;}Assert(red>200&&orange>20&&coal>25,"Не хватает деталей снеговика");}});
   Test("A44","Снегоуборщик расчищает полосу перед отвалом",delegate{var w=World();var s=new Surface(-1,-800,1000,1600){Floor=true};for(int i=0;i<s.Heights.Length;i++)s.Heights[i]=20;w.Surfaces.Add(s);w.Plowing=true;w.PlowX=0;w.Advance(SnowWorld.Step);Near(s.Height(50),0,.001,"Снег перед отвалом остался");Assert(s.Height(150)>15,"Очистка затронула дальнюю область");});
   Test("A45","Крупный упавший комок оседает и не теряет площадь",delegate{var w=World();var floor=new Surface(-1,-800,1000,1600){Floor=true};w.Surfaces.Add(floor);double mass=Math.PI*35*35;w.Flakes.Add(new Flake{X=0,Y=100,VY=100,Radius=35,Clump=true,Debris=true,SnowArea=mass});for(int i=0;i<300;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count==0,"Комок не приземлился");Near(floor.Area,mass,.01,"Количество снега после приземления");});
   Test("A46","Нижний снег может заполнить экран, оконный слой ограничен",delegate{var w=World();w.Settings.FillDesktop=true;w.Sync(new List<WindowInfo>(),new List<Rectangle>());var floor=w.Surfaces.First(v=>v.Floor);floor.Add(0,1e9);Near(floor.Area,1600*1000,.01,"Не заполнен экран");Near(floor.Height(0),1000,.01,"Не достигнут верх");var ledge=new Surface(1,0,300,300);ledge.Add(100,1e9);Near(ledge.Area,300*60,.01,"Изменён оконный предел");using(var path=ScenePainter.SnowPath(floor))Assert(path.IsVisible(0,1)&&path.IsVisible(0,999),"Не отрисовано полное заполнение");});
   Test("A47","Выключение и смена экрана обновляют предел нижнего снега",delegate{var w=World();w.Settings.FillDesktop=true;w.Sync(new List<WindowInfo>(),new List<Rectangle>());var floor=w.Surfaces.First(v=>v.Floor);floor.Add(0,1e9);w.Settings.FillDesktop=false;w.RefreshGroundLimits();Near(floor.Height(0),60,.01,"Не восстановлен обычный предел");w.Settings.FillDesktop=true;w.RefreshGroundLimits();Near(floor.MaxHeight,1000,.01,"Не включён высокий предел");w.Monitors[0]=new Rectangle(-800,-200,1600,700);w.Sync(new List<WindowInfo>(),new List<Rectangle>());Near(floor.MaxHeight,700,.01,"Не обновлён размер монитора");});
   Test("A48","Снегопад продолжает пополнять высокий нижний сугроб",delegate{var w=World();w.Settings.FillDesktop=true;w.Settings.Intensity=350;w.Settings.Wind=0;w.Emitting=true;w.Sync(new List<WindowInfo>(),new List<Rectangle>());var floor=w.Surfaces.First(v=>v.Floor);for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=900;double before=floor.Area;for(int i=0;i<360;i++)w.Advance(SnowWorld.Step);Assert(floor.Area>before+100,"Высокий снег не пополняется");Assert(floor.Heights.All(v=>v<=1000.001),"Превышена высота экрана");});
   Test("A49","Настройка заполнения сохраняется, по умолчанию выключена",delegate{Assert(!new Settings().FillDesktop,"Неверное начальное значение");string file=Path.Combine(dir,"fill-desktop-test.xml");try{new Settings{FillDesktop=true}.Save(file);Assert(Settings.Load(file).FillDesktop,"Не сохранено");File.WriteAllText(file,"<Settings><Intensity>90</Intensity></Settings>");Assert(!Settings.Load(file).FillDesktop,"Нарушена совместимость старых настроек");}finally{if(File.Exists(file))File.Delete(file);}});
   Test("A50","Звуковые настройки сохраняются и ограничены диапазоном",delegate{var settings=new Settings{SoundEnabled=false,SoundVolume=200,LightSound=-1,PlowSound=0,BallSound=23,ShovelSound=45,MittenSound=67,BlizzardSound=81};string file=Path.Combine(dir,"audio-test.xml");try{settings.Save(file);var loaded=Settings.Load(file);Assert(!loaded.SoundEnabled&&loaded.SoundVolume==100&&loaded.LightSound==0&&loaded.PlowSound==0&&loaded.BallSound==23&&loaded.ShovelSound==45&&loaded.MittenSound==67&&loaded.BlizzardSound==81,"Потеря настройки");}finally{if(File.Exists(file))File.Delete(file);}});
   Test("A51","Общий выключатель, нулевая громкость и пауза дают тишину PCM",delegate{var w=World();w.Emitting=true;w.Plowing=true;using(var audio=new SoundEngine(w.Settings,false)){audio.Update(w,true);audio.Trigger("ball",1000);Assert(audio.Samples(1000).Any(v=>v!=0),"Нет сигнала");w.Settings.SoundEnabled=false;audio.Update(w,true);Assert(audio.Samples(1000).All(v=>v==0),"Выключатель не отключил звук");w.Settings.SoundEnabled=true;w.Settings.SoundVolume=0;audio.Update(w,true);Assert(audio.Samples(1000).All(v=>v==0),"Ноль не выключил звук");w.Settings.SoundVolume=50;w.Paused=true;audio.Update(w,true);Assert(audio.Samples(1000).All(v=>v==0),"Пауза не остановила звук");w.Paused=false;audio.Update(w,false);Assert(audio.Samples(1000).All(v=>v==0),"Выключенный эффект звучит");}});
   Test("A52","Все отдельные звуки имеют независимое отключение",delegate{var w=World();foreach(string kind in new[]{"ball","shovel","mitten"}){using(var audio=new SoundEngine(w.Settings,false)){w.Emitting=false;w.Plowing=false;audio.Update(w,true);audio.Trigger(kind,5000);Assert(audio.Samples(1000).Any(v=>v!=0),"Нет звука "+kind);int original=kind=="ball"?w.Settings.BallSound:kind=="shovel"?w.Settings.ShovelSound:w.Settings.MittenSound;if(kind=="ball")w.Settings.BallSound=0;else if(kind=="shovel")w.Settings.ShovelSound=0;else w.Settings.MittenSound=0;audio.Update(w,false);audio.Update(w,true);audio.Trigger(kind,5000);Assert(audio.Samples(1000).All(v=>v==0),"Не выключен "+kind);if(kind=="ball")w.Settings.BallSound=original;else if(kind=="shovel")w.Settings.ShovelSound=original;else w.Settings.MittenSound=original;}}foreach(int intensity in new[]{40,90,260}){using(var audio=new SoundEngine(w.Settings,false)){w.Emitting=true;w.Settings.Intensity=intensity;audio.Update(w,true);Assert(audio.Samples(1000).Any(v=>v!=0),"Нет фона");w.Settings.LightSound=w.Settings.NormalSound=w.Settings.BlizzardSound=0;audio.Update(w,true);Assert(audio.Samples(1000).All(v=>v==0),"Не выключен фон");w.Settings.LightSound=35;w.Settings.NormalSound=55;w.Settings.BlizzardSound=80;}}w.Emitting=false;w.Plowing=true;using(var audio=new SoundEngine(w.Settings,false)){audio.Update(w,true);Assert(audio.Samples(1000).Any(v=>v!=0),"Нет двигателя");w.Settings.PlowSound=0;audio.Update(w,true);Assert(audio.Samples(1000).All(v=>v==0),"Не выключен двигатель");}});
   Test("A53","Инструменты издают звук при заборе настоящего снега",delegate{foreach(Tool tool in new[]{Tool.Snowball,Tool.Shovel,Tool.Mitten}){var w=World();var surface=new Surface(1,-100,200,200);for(int i=0;i<surface.Heights.Length;i++)surface.Heights[i]=20;w.Surfaces.Add(surface);int events=0;w.Sound=delegate(string kind,double amount){if(amount>0)events++;};w.Tool=tool;w.BeginDrag(new PointF(0,180));Assert(events>0,"Нет события "+tool);w.Clear();events=0;w.BeginDrag(new PointF(0,180));Assert(events==0,"Звук пустого снега");}});
   Test("A54","Отвал собирает снег в вал и выбрасывает комки по дуге",delegate{var w=World();var floor=new Surface(-1,-800,1000,1600){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=30;w.Surfaces.Add(floor);double before=floor.Area;w.Plowing=true;w.PlowX=0;for(int i=0;i<7;i++)w.Advance(SnowWorld.Step);var spray=w.Flakes.Where(f=>f.PlowSpray).ToList();Assert(floor.PlowBank>0&&spray.Count>0,"Нет вала или выброса");Assert(spray.All(f=>f.VY<0&&f.VX<0),"Нет дуги в сторону");Near(before,floor.Area+floor.PlowBank+spray.Sum(f=>f.SnowArea),.01,"Снег исчез до выброса");});
   Test("A55","Глубокий снег замедляет машину, очистка сбрасывает вал",delegate{double[] moved=new double[2];for(int k=0;k<2;k++){var w=World();var floor=new Surface(-1,-800,1000,1600){Floor=true,MaxHeight=1000};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=k==0?10:500;w.Surfaces.Add(floor);w.Plowing=true;w.PlowX=0;w.Advance(SnowWorld.Step);moved[k]=w.PlowX;w.Clear();Assert(floor.PlowBank==0&&!w.Plowing&&w.Flakes.Count==0,"Очистка оставила машину или снег");}Assert(moved[1]<moved[0]*.6,"Нет замедления");});
   Test("A56","Бюджет частиц удерживает собранный вал до выброса",delegate{var w=World();w.EffectiveLimit=1;w.Flakes.Add(new Flake{X=0,Y=-500,VY=0,Radius=1});var floor=new Surface(-1,-800,1000,1600){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);w.Plowing=true;w.PlowX=0;for(int i=0;i<10;i++)w.Advance(SnowWorld.Step);Assert(floor.PlowBank>0&&w.Flakes.Count==1,"Превышен бюджет");w.Flakes.Clear();w.Advance(SnowWorld.Step);Assert(w.Flakes.Any(f=>f.PlowSpray),"Отложенный выброс не начался");});
   Test("A57","Горсть забирает реальный снег и бросает россыпью с сохранением площади",delegate{var w=World();var floor=new Surface(-1,-100,200,200){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);double before=floor.Area;w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,180));Assert(w.Held!=null&&w.Held.Loose&&w.Held.Area>0&&w.Held.Radius<=22.001,"Не взята горсть");Near(before,floor.Area+w.Held.Area,.01,"Снег создан из воздуха");w.Advance(.05);w.EndDrag(new PointF(50,120));Assert(w.Held==null&&w.Balls.Count==0&&w.Flakes.Count>=8,"Не создана россыпь");Near(before,floor.Area+w.Flakes.Sum(f=>f.SnowArea),.01,"Потеря площади");});
   Test("A58","Отмена инструмента отпускает горсть и не оставляет захват",delegate{var w=World();var floor=new Surface(-1,-100,200,200){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);double before=floor.Area;w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,180));w.CancelDrag();Assert(w.Held==null&&!w.ToolDown&&w.Balls.Count==0,"Остался захват");Near(before,floor.Area+w.Flakes.Sum(f=>f.SnowArea),.01,"Потеря при отмене");});
   Test("A59","Сильный удар брошенного снежка разбивает его на комки",delegate{var w=World();var floor=new Surface(-1,-200,200,400){Floor=true};w.Surfaces.Add(floor);double area=Math.PI*100;var ball=new Ball{X=0,Y=170,VY=1000,Area=area,ThrowArmed=true};w.Balls.Add(ball);for(int i=0;i<8;i++)w.Advance(SnowWorld.Step);Assert(!w.Balls.Contains(ball)&&w.Flakes.Count>0,"Снежок не разбился");Near(area,floor.Area+w.Flakes.Sum(f=>f.SnowArea),.01,"Потеря площади при ударе");});
   Test("A60","Мягкое приземление сохраняет снежок целым",delegate{var w=World();var floor=new Surface(-1,-200,200,400){Floor=true};w.Surfaces.Add(floor);var ball=new Ball{X=0,Y=175,VY=50,Area=Math.PI*100,ThrowArmed=true};w.Balls.Add(ball);for(int i=0;i<60;i++)w.Advance(SnowWorld.Step);Assert(w.Balls.Contains(ball)&&ball.Support==floor&&!ball.ThrowArmed&&w.Flakes.Count==0,"Мягкий удар разрушил шар");});
   Test("A61","Сильный взмах вооружает снежок для разрушения",delegate{var w=World();w.Tool=Tool.Snowball;var ball=new Ball{X=0,Y=100,Area=Math.PI*100};w.Balls.Add(ball);w.BeginDrag(new PointF(0,100));w.Advance(.05);w.EndDrag(new PointF(100,100));Assert(ball.ThrowArmed&&ball.VX>=650&&!ball.Held,"Сильный бросок не распознан");});
   Test("A62","При полном бюджете частицы горсти возвращаются в снег",delegate{var w=World();var floor=new Surface(-1,-100,200,200){Floor=true};w.Surfaces.Add(floor);w.EffectiveLimit=0;w.Scatter(100,0,100,500,-100,floor);Near(floor.Area,100,.01,"Потеря при полном бюджете");Assert(w.Flakes.Count==0,"Превышен бюджет");});
   Test("A63","Случайный въезд выбирает обе стороны экрана",delegate{var w=World();bool left=false,right=false;for(int i=0;i<50;i++){w.StartPlow();if(w.PlowDirection==1){left=true;Assert(w.PlowX==-850,"Неверный левый въезд");}else{right=true;Assert(w.PlowX==850,"Неверный правый въезд");}}Assert(left&&right,"Не выбраны обе стороны");});
   Test("A64","Правый въезд разворачивает отвал, движение и выброс",delegate{var w=World();var floor=new Surface(-1,-800,1000,1600){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);w.Plowing=true;w.PlowDirection=-1;w.PlowX=0;for(int i=0;i<7;i++)w.Advance(SnowWorld.Step);Assert(w.PlowX<0&&floor.Height(-50)<1&&floor.Height(150)>10,"Неверная сторона очистки");Assert(w.Flakes.Any(f=>f.PlowSpray&&f.VX>0),"Выброс не развернулся");w.PlowX=-900;w.Advance(SnowWorld.Step);Assert(!w.Plowing,"Нет завершения слева");});
   Test("A65","Слабая горсть летит в сторону жеста, в том числе после неподвижного опроса",delegate{foreach(int direction in new[]{-1,1}){var w=World();var floor=new Surface(-1,-400,300,800){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,280));w.Advance(.05);w.Drag(new PointF(direction,280));w.Advance(.025);w.Drag(new PointF(direction,280));w.EndDrag(new PointF(direction,280));Assert(w.Flakes.Count>=8&&w.Flakes.All(f=>f.VX*direction>0),"Разброс перебил направление слабого броска");for(int i=0;i<14;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count>=8,"Комки мгновенно вернулись");double center=w.Flakes.Sum(f=>f.X*f.SnowArea)/w.Flakes.Sum(f=>f.SnowArea);Assert((center-direction)*direction>8,"Нет полёта по направлению жеста");}});
   Test("A66","При отпускании без взмаха горсть видимо падает, а не телепортируется",delegate{var w=World();var floor=new Surface(-1,-400,300,800){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);double before=floor.Area;w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,280));for(int i=0;i<30;i++)w.Advance(SnowWorld.Step);w.EndDrag(new PointF(0,280));for(int i=0;i<12;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count>0&&floor.Area<before,"Мгновенный возврат");Near(before,floor.Area+w.Flakes.Sum(f=>f.SnowArea),.01,"Потеря снега");});
   Test("A67","Защита от исходного сугроба временная: брошенный снег затем оседает",delegate{var w=World();var floor=new Surface(-1,-400,300,800){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);double before=floor.Area;w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,280));w.Advance(.05);w.EndDrag(new PointF(1,280));for(int i=0;i<180;i++)w.Advance(SnowWorld.Step);Assert(w.Flakes.Count==0,"Остались комки: "+string.Join(";",w.Flakes.Select(f=>string.Format("x={0:F1}, y={1:F1}, age={2:F2}, top={3:F1}",f.X,f.Y,f.Age,floor.Y-floor.Height(f.X)))));Near(floor.Area,before,.1,"Количество снега после посадки");});
   Test("A68","Полный бюджет не возвращает брошенную горсть в исходную кучу",delegate{var w=World();var floor=new Surface(-1,-400,300,800){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);w.EffectiveLimit=0;double before=floor.Area;w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,280));w.Advance(.05);w.EndDrag(new PointF(1,280));Assert(w.Held==null&&w.Balls.Count==1&&w.Balls[0].Loose&&!w.Balls[0].Held&&floor.Area<before,"Горсть вернулась вместо полёта");double x=w.Balls[0].X;w.Advance(.05);Assert(w.Balls[0].X>x,"Нет полёта без свободных частиц");w.EffectiveLimit=100;w.Advance(SnowWorld.Step);Assert(w.Balls.Count==0&&w.Flakes.Count>0,"Не создана отложенная россыпь");Near(before,floor.Area+w.Flakes.Sum(f=>f.SnowArea),.01,"Потеря в очереди");});
   Test("A69","При долгом полном бюджете горсть долетает и естественно оседает",delegate{var w=World();var floor=new Surface(-1,-400,300,800){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);w.EffectiveLimit=0;double before=floor.Area;w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,280));w.Advance(.05);w.EndDrag(new PointF(1,280));for(int i=0;i<240;i++)w.Advance(SnowWorld.Step);Assert(w.Balls.Count==0&&w.Flakes.Count==0,"Горсть не приземлилась");Near(before,floor.Area,.1,"Потеря при долгом полном бюджете");});
   Test("A70","Бросок вниз вдали от сугроба сохраняет направление вниз",delegate{var w=World();var floor=new Surface(-1,-400,300,800){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);w.Tool=Tool.Handful;w.BeginDrag(new PointF(0,280));w.Advance(.05);w.Drag(new PointF(0,100));w.Advance(.05);w.EndDrag(new PointF(0,101));Assert(w.Flakes.Count>0&&w.Flakes.All(f=>f.VY>0),"Направление вниз заменено подъёмом");});
   PreviewHandful(dir);PreviewPlow(dir);Preview(dir);
   var report="# Автоматические испытания Снег 0.8.1\r\n\r\nДата UTC: "+DateTime.UtcNow.ToString("o")+"\r\nОС: "+Environment.OSVersion+"\r\n\r\nЭти испытания запускают физику и настройки. Они не доказывают пропуск настоящего ввода, видимость на рабочем столе, поддержку DPI или отсутствие утечек в оконной системе.\r\n\r\n| ID | Проверка | Результат | Подробность |\r\n|---|---|---|---|\r\n"+string.Join("\r\n",results)+"\r\n\r\nПройдено: "+(results.Count-failed)+" / "+results.Count+". Код завершения: "+(failed==0?0:1)+".\r\n";
   File.WriteAllText(Path.Combine(dir,"automated-results.md"),report,Encoding.UTF8);return failed==0?0:1;
  }
  static void PreviewHandful(string dir){var w=World();w.Settings.Wind=0;w.Monitors.Clear();w.Monitors.Add(new Rectangle(0,0,600,300));var floor=new Surface(-1,0,300,600){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=20;w.Surfaces.Add(floor);w.Tool=Tool.Handful;w.BeginDrag(new PointF(200,280));w.Advance(.05);w.EndDrag(new PointF(201,280));for(int frame=0;frame<20;frame++){using(var image=new Bitmap(600,300))using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(26,42,66));g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;ScenePainter.Draw(g,w,false,false,0);using(var font=new Font("Segoe UI",11))g.DrawString("ПРЕДПРОСМОТР · СЛАБЫЙ БРОСОК ВПРАВО →",font,Brushes.LightSteelBlue,18,18);image.Save(Path.Combine(dir,"Evidence/handful-v081-"+frame.ToString("D2")+".png"));}for(int i=0;i<6;i++)w.Advance(SnowWorld.Step);}}
  static void PreviewPlow(string dir){var w=World();w.Monitors.Clear();w.Monitors.Add(new Rectangle(0,0,1000,320));var floor=new Surface(-1,0,320,1000){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=32+Math.Sin(i*.12)*6;w.Surfaces.Add(floor);w.Plowing=true;w.PlowX=120;for(int frame=0;frame<12;frame++){for(int j=0;j<15;j++)w.Advance(SnowWorld.Step);using(var image=new Bitmap(1000,320))using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(26,42,66));g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;ScenePainter.Draw(g,w,false,false,0);using(var font=new Font("Segoe UI",12))g.DrawString("ПРЕДПРОСМОТР · УБОРКА СНЕГА 0.7",font,Brushes.LightSteelBlue,20,20);image.Save(Path.Combine(dir,"Evidence/plow-v07-"+frame.ToString("D2")+".png"));}}}
  static void Preview(string dir){
   var w=World();w.Monitors.Clear();w.Monitors.Add(new Rectangle(0,0,1000,650));var ledge=new Surface(1,40,330,480);for(int i=0;i<ledge.Heights.Length;i++)ledge.Heights[i]=19+Math.Sin(i*.25)*2;w.Surfaces.Add(ledge);var floor=new Surface(-1,0,650,1000){Floor=true};for(int i=0;i<floor.Heights.Length;i++)floor.Heights[i]=15+Math.Sin(i*.12)*2;w.Surfaces.Add(floor);
   var bottom=new Ball{X=365,Y=274,Area=Math.PI*37*37,Support=ledge};var middle=new Ball{X=365,Y=208,Area=Math.PI*30*30,Support=ledge,OnBall=bottom};var head=new Ball{X=365,Y=148,Area=Math.PI*31*31,Support=ledge,OnBall=middle,Face=true};w.Balls.Add(bottom);w.Balls.Add(middle);w.Balls.Add(head);w.Balls.Add(new Ball{X=758,Y=170,Area=Math.PI*55*55});w.Plowing=true;w.PlowX=785;
   w.Flakes.Add(new Flake{X=659,Y=370,Radius=12,Clump=true,SnowArea=Math.PI*144,Phase=.4});w.Flakes.Add(new Flake{X=810,Y=365,Radius=36,Clump=true,SnowArea=Math.PI*1296,Phase=1.2,Spin=15});
   using(var image=new Bitmap(1000,650))using(var g=Graphics.FromImage(image)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.Clear(Color.FromArgb(29,42,59));using(var card=new System.Drawing.Drawing2D.GraphicsPath()){card.AddArc(40,330,48,48,180,90);card.AddArc(472,330,48,48,270,90);card.AddLine(520,354,520,565);card.AddLine(520,565,40,565);card.CloseFigure();using(var b=new SolidBrush(Color.FromArgb(13,21,34)))g.FillPath(b,card);using(var pen=new Pen(Color.FromArgb(91,112,134),1))g.DrawPath(pen,card);}using(var title=new Font("Segoe UI",14))g.DrawString("ПРЕДПРОСМОТР ОТРИСОВКИ · СНЕГ 0.4",title,Brushes.LightSteelBlue,35,23);using(var label=new Font("Segoe UI",12)){g.DrawString("Снеговик и снежный свес",label,Brushes.LightSteelBlue,65,395);g.DrawString("Зернистый снежок",label,Brushes.LightSteelBlue,663,245);g.DrawString("Размер кучек зависит от количества снега",label,Brushes.LightSteelBlue,580,438);}ScenePainter.Draw(g,w,false,false,0);image.Save(Path.Combine(dir,"Evidence/appearance-v04.png"),System.Drawing.Imaging.ImageFormat.Png);}
